import hashlib, itertools
def shingles(text, n=5):                       # 낱말 5-gram 집합
    w = text.lower().split()
    return {" ".join(w[i:i + n]) for i in range(len(w) - n + 1)}
def minhash(sh, k=128):                        # 해시 함수 k 개 각각의 최솟값
    return [min(int(hashlib.md5(f"{s}|{x}".encode()).hexdigest()[:8], 16) for x in sh)
            for s in range(k)]
docs = {"a": "the quick brown fox jumps over the lazy dog near the river bank today",
        "b": "the quick brown fox jumps over the lazy dog near the river bank yesterday",
        "c": "language models are trained on large amounts of filtered web text data"}
S = {k: shingles(v) for k, v in docs.items()}
M = {k: minhash(v) for k, v in S.items()}
for x, y in itertools.combinations(docs, 2):
    jac = len(S[x] & S[y]) / len(S[x] | S[y])
    est = sum(p == q for p, q in zip(M[x], M[y])) / len(M[x])
    print(f"{x}-{y}: Jaccard {jac:.3f}  MinHash 추정 {est:.3f}")
b, r = 16, 8                                   # 밴드 16개 × 밴드당 8행 = 128
for s in (0.5, 0.7, 0.8, 0.9):
    print(f"유사도 {s}: 후보로 잡힐 확률 {1 - (1 - s ** r) ** b:.3f}")

pr = {"title": "Fix off-by-one in pager", "user": "kim", "repo": "acme/web",
      "files": [{"path": "pager.py", "context": "def page(start, size):",
                 "hunk": ["-    end = start + size + 1", "+    end = start + size"]}],
      "events": [{"type": "comment", "user": "lee", "body": "LGTM, add a test?"},
                 {"type": "review", "user": "lee", "state": "approved"}]}
def linearize(pr, with_context=True):
    out = [f"<pr_title>{pr['title']}", f"<pr_user>{pr['user']}", f"<pr_repo>{pr['repo']}"]
    for f in pr["files"]:
        out.append(f"<pr_file>{f['path']}")
        if with_context: out.append(f"<pr_base_code>{f['context']}")   # 주변 맥락을 얼마나?
        out += [f"<pr_diff_hunk>{h}" for h in f["hunk"]]
    for e in pr["events"]:                                 # 시간 순 사건을 한 줄씩
        out.append(f"<pr_comment>{e['user']}: {e['body']}" if e["type"] == "comment"
                   else f"<pr_review_state>{e['state']}")
    return "\n".join(out)
for ctx in (False, True):
    s = linearize(pr, ctx)
    print(f"--- 맥락 {ctx}: {len(s.encode())} B ≈ {len(s.encode()) / 2.54:.0f} 토큰(코드 2.54 B/tok)")
print(s)
